// Query Hermes session DB for recent completed sessions
// This calls the Hermes API to get session history
return [{json: {query: 'recent_sessions', timestamp: new Date().toISOString()}}];

// Parse AI output and prepare for Qdrant storage
const data = JSON.parse($input.item.json.output || $input.item.json.text || '{}');
const lessons = (data.lessons || []).map(l => ({
  json: {
    collection: 'nura_lessons',
    id: l.id,
    vector: null,  // Qdrant will generate embedding
    payload: {
      category: l.category,
      content: l.content,
      related_skill: l.related_skill || '',
      timestamp: new Date().toISOString(),
      session_id: data.session_id || 'auto'
    }
  }
}));
return lessons.length ? lessons : [{json: {status: 'no_new_lessons'}}];

// Count lessons extracted
const lessons = $input.all();
const count = lessons.filter(l => l.json.id).length;
return [{json: {status: 'complete', lessons_extracted: count, timestamp: new Date().toISOString()}}];
